using System;
using System.Collections.Generic;
using UnityEngine;

namespace Kott.Configs
{
    /// <summary>
    ///     Maps the type identifiers in config payloads to template types. Generated by the editor for every template
    ///     type in use and its base types; needed to read payloads and to group templates by type at runtime.
    /// </summary>
    public class ConfigTypeMapping : ScriptableObject
    {
        /// <summary>One template type: identifier, assembly-qualified type name and base types.</summary>
        [Serializable]
        public class Group
        {
            [SerializeField]
            private string _typeIdentifier;

            [SerializeField]
            private string _typeString;

            [SerializeField]
            private List<string> _baseTypeStrings = new();

            /// <summary>Identifier of the type in payloads (see <see cref="TemplateIdUtility.GetTypeIdentifier" />).</summary>
            public string TypeIdentifier
            {
                get => _typeIdentifier;
                set => _typeIdentifier = value;
            }

            /// <summary>Assembly-qualified name of the template type.</summary>
            public string TypeString
            {
                get => _typeString;
                set => _typeString = value;
            }

            /// <summary>Assembly-qualified names of the type and its base types, up to <see cref="Template" />.</summary>
            public List<string> BaseTypeStrings => _baseTypeStrings;
        }

        [SerializeField]
        private List<Group> _typeGroups = new();

        /// <summary>All mapped types.</summary>
        public List<Group> TypeGroups => _typeGroups;

        /// <summary>Creates a mapping for <paramref name="templateTypes" /> and their base types (e.g. for tests).</summary>
        public static ConfigTypeMapping Create(params Type[] templateTypes)
        {
            ConfigTypeMapping mapping = CreateInstance<ConfigTypeMapping>();
            foreach (Type type in templateTypes)
            {
                mapping.Add(type);
            }

            return mapping;
        }

        /// <summary>
        ///     Adds <paramref name="templateType" /> and its base types up to <see cref="Template" /> (if not mapped yet),
        ///     with identifiers from <see cref="TemplateIdUtility.GetTypeIdentifier" />.
        /// </summary>
        public void Add(Type templateType)
        {
            if (templateType == null) throw new ArgumentNullException(nameof(templateType));
            if (!typeof(Template).IsAssignableFrom(templateType))
            {
                throw new ArgumentException($"{templateType.FullName} is not a {nameof(Template)} type.",
                    nameof(templateType));
            }

            for (Type type = templateType; type != typeof(Template); type = type.BaseType)
            {
                if (_typeGroups.Exists(group => group.TypeString == type.AssemblyQualifiedName)) continue;

                Group group = new()
                {
                    TypeIdentifier = TemplateIdUtility.GetTypeIdentifier(type),
                    TypeString = type.AssemblyQualifiedName,
                };
                for (Type baseType = type;
                     baseType != null && baseType != typeof(ScriptableObject);
                     baseType = baseType.BaseType)
                {
                    group.BaseTypeStrings.Add(baseType.AssemblyQualifiedName);
                }

                _typeGroups.Add(group);
            }
        }

        /// <summary>
        ///     Resolves the mapped types: identifier → type.
        /// </summary>
        /// <exception cref="ConfigException">A type no longer exists, or two types share an identifier.</exception>
        public Dictionary<string, Type> ResolveTypes()
        {
            Dictionary<string, Type> types = new();
            foreach (Group group in _typeGroups)
            {
                Type type = Type.GetType(group.TypeString);
                if (type == null)
                {
                    throw new ConfigException(
                        $"Type mapping '{name}': type '{group.TypeString}' (identifier '{group.TypeIdentifier}') not " +
                        "found. Was the class renamed or moved? Regenerate the mapping; pin identifiers with " +
                        "[TemplateType] to keep published payloads valid.");
                }

                if (types.TryGetValue(group.TypeIdentifier, out Type other))
                {
                    throw new ConfigException(
                        $"Type mapping '{name}': identifier '{group.TypeIdentifier}' is used by {other.FullName} and " +
                        $"{type.FullName}. Pin distinct identifiers with [TemplateType].");
                }

                types.Add(group.TypeIdentifier, type);
            }

            return types;
        }
    }
}
